def policy_check(ctx: dict, action: str) -> tuple[bool, str]:
    # one place that says yes/no for EVERY tool call
    # ctx carries user, session, and running usage counters
    if not allowed(action):
        return False, f"'{action}' is not on the allow list"
    if over_budget(ctx):
        return False, "budget exceeded"
    return True, "ok"

ok, reason = policy_check(ctx, "issue_refund")
if not ok:
    raise PermissionError(reason)   # tool never runs

budgets = {"user:42": {"limit_usd": 5.00, "spent_usd": 0.0}}

def charge(key: str, cost_usd: float) -> bool:
    b = budgets[key]
    if b["spent_usd"] + cost_usd > b["limit_usd"]:
        return False           # would exceed the ceiling -> deny
    b["spent_usd"] += cost_usd  # commit the spend
    return True

print(charge("user:42", 2.0))  # True, now spent 2.00
print(charge("user:42", 4.0))  # False, would exceed 5.00 -> denied

class Dispatcher:
    def __init__(self):
        self.killed = False        # flip to True to stop everything
    def call(self, ctx, action, cost_usd, tool_fn, **kwargs):
        if self.killed:
            raise PermissionError("kill switch engaged")
        if not allowed(action):
            raise PermissionError(f"'{action}' denied by policy")
        if not under_rate_limit(ctx["user"], limit=30):
            raise PermissionError("rate limit exceeded")
        if not charge(ctx["user"], cost_usd):
            raise PermissionError("budget exceeded")
        return tool_fn(**kwargs)   # all gates passed -> run

