ALLOW = {"search", "read_file", "summarize"}
DENY  = {"run_shell", "delete_all"}

def evaluate(action: str) -> str:
    if action in DENY:
        return "DENY (explicitly forbidden)"
    if action in ALLOW:
        return "ALLOW"
    return "DENY (not on allow list)"   # default-deny

for action in ["search", "run_shell", "transfer_funds"]:
    print(f"{action}: {evaluate(action)}")

import time
from collections import defaultdict

ALLOW = {"search", "summarize"}

class Policy:
    def __init__(self):
        self.killed = False
        self.calls = defaultdict(list)
        self.budget = defaultdict(lambda: {"limit": 1.00, "spent": 0.0})

    def _rate_ok(self, key, limit=5, window=60.0):
        now = time.time()
        self.calls[key] = [t for t in self.calls[key] if now - t < window]
        if len(self.calls[key]) >= limit:
            return False
        self.calls[key].append(now)
        return True

    def call(self, user, action, cost, tool_fn, **kwargs):
        if self.killed:
            raise PermissionError("kill switch engaged")
        if action not in ALLOW:
            raise PermissionError(f"'{action}' denied by policy")
        if not self._rate_ok(user):
            raise PermissionError("rate limit exceeded")
        b = self.budget[user]
        if b["spent"] + cost > b["limit"]:
            raise PermissionError("budget exceeded")
        b["spent"] += cost                 # meter the spend
        return tool_fn(**kwargs)

p = Policy()
print(p.call("u1", "search", 0.60, lambda q: f"results for {q}", q="agents"))
try:
    p.call("u1", "search", 0.60, lambda q: "...", q="more")  # would hit 1.20 > 1.00
except PermissionError as e:
    print("denied:", e)
